      "content": "{\n  \"name\": \"dsh-damage-pulse\",\n  \"version\": \"4.3.2\",\n  \"description\": \"DeepSeek Harness balance monitor with a whale-girl companion and cache-aware damage animations for every token charge.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"assets/**/*\",\n    \"docs/assets/dsh-damage-pulse-peak-valley-whale-poster.png\",\n    \"docs/assets/fastaitoken-channel-models.png\",\n    \"docs/assets/readme/dsh-damage-pulse-wechat-live.jpg\",\n    \"docs/assets/readme/usage-details.png\",\n    \"docs/assets/readme/usage-details-columns.png\",\n    \"docs/assets/readme/usage-details-by-provider.png\",\n    \"docs/assets/readme/fee-explanation.png\",\n    \"docs/assets/readme/billing-rules.png\",\n    \"docs/assets/readme/balance-script.png\",\n    \"docs/assets/readme/notification-settings.png\",\n    \"docs/assets/readme/settings-dialog.png\",\n    \"docs/assets/readme/usage-overview.png\",\n    \"docs/assets/readme/plan-quota.png\",\n    \"docs/assets/readme/workspace-overview.png\",\n    \"docs/assets/readme/wechat-sponsor-qr.png\",\n    \"docs/assets/readme/module-management.png\",\n    \"docs/assets/readme/balance-card-usage.png\",\n    \"docs/assets/readme/balance-card-no-credentials.png\",\n    \"docs/assets/readme/balance-card-context-menu.png\",\n    \"docs/assets/readme/whale-girl-critical-damage.png\",\n    \"docs/assets/readme/whale-girl-idle-bite-finger.png\",\n    \"patches/**/*\",\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"runtime/**/*\",\n    \"cordis.patch.yml\",\n    \"tsconfig.bundle.json\",\n    \"README.md\",\n    \"README.en.md\",\n    \"docs/REFERENCE.zh-CN.md\",\n    \"docs/REFERENCE.en.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"test\": \"node --test tests/*.test.ts && vitest run packages/util/token-mo