      "path": "plugins/dsh-token-monitor/src/balance-provider.ts",
      "content": "/** Resolve only the selected provider's current explicit credential reference. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { credentialRef } from '@deepseek-ai/dsh-credentials'\nimport { launchEnvironmentOf } from '@deepseek-ai/dsh-launch-environment'\nimport type {} from '@deepseek-ai/dsh-llm'\nimport type {} from '@deepseek-ai/dsh-settings'\nimport type { BalanceIdentity } from './balance-registry.ts'\nimport type { BalanceProviderEntry } from './balance-storage.ts'\nimport { isOfficialProvider } from './pricing.ts'\n\n/**\n * API base URLs for known configurable providers whose profiles omit an\n * explicit baseURL. Mirrors the launch adapter defaults so balance querying\n * works the moment a provider is configured; an explicit profile baseURL\n * always wins.\n */\nconst PROVIDER_BASE_URL_FALLBACKS: Record<string, string> = Object.freeze({\n  'zai-coding-cn': 'https://open.bigmodel.cn/api/coding/paas/v4',\n  'zai-coding': 'https://api.z.ai/api/coding/paas/v4',\n  'kimi-coding': 'https://api.kimi.com/coding/v1',\n  'minimax-cn': 'https://api.minimaxi.com/anthropic',\n  'minimax': 'https://api.minimax.io/anthropic',\n})\n\n/** Read the provider profile via its owning adapter's settings directory.\n * @param ctx Context with LLM, settings and credentials.\n * @param provider Exact configured route.\n * @returns Key and endpoint for server-internal use, or undefined when unavailable.\n */\nexport async function resolveBalanceIdentity(\n  ctx: Context,\n  provider: string,\n  balanceProvider?: BalanceProviderEntry,\n): Promise<BalanceIdentity | undefined> {\n  if (balanceProvider !== undefined) {\n    const resolved = await ctx.credentials.resolve(credentialRef(balanceProvider.apiKeyEnv))\n    if (!resolved?.value) return undefined\n    return { apiKey: resolved.value, baseURL: balanceProvider.baseURL }\n  }\n  const descriptor = ctx.llm.listConfigurableProviders().find(item => item.provider === provider)\n  if (!descriptor || descriptor.error) return undefined\n  // 活配置里没有该 namespace 的描述符时视为不可解析。\n  let profile: unknown = ctx.settings.describe().find(item => item.ns === descriptor.settingsNs)?.value\n  for (const key of descriptor.settingsPath) {\n    if (!profile || typeof profile !== 'object') return undefined\n    profile = (profile as Record<string, unknown>)[key]\n  }\n  if (!profile || typeof profile !== 'object') return undefined\n  const fields = profile as Record<string, unknown>\n  const official = isOfficialProvider(provider)\n    && (descriptor.settingsNs === 'llm-deepseek' || descriptor.settingsNs === 'llm-deepseek-account')\n  const ref = fields.apiKeyEnv ?? (official ? 'DEEPSEEK_API_KEY' : undefined)\n  const baseURL = fields.baseURL ?? (official ? launchEnvironmentOf(ctx).get('DEEPSEEK_BASE_URL')?.value ?? 'https://api.deepseek.com' : undefined)\n    ?? PROVIDER_BASE_URL_FALLBACKS[provider]\n  if (typeof ref !== 'string' || !ref || typeof baseURL !== 'string') return undefined\n  const resolved = await ctx.credentials.resolve(credentialRef(ref))\n  if (!resolved?.value) return undefined\n  return { apiKey: resolved.value, baseURL }\n}\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/balance-registry.ts",
      "content": "/** Provider-specific balance requests with credential rotation and stale-result rejection. */\nimport { randomUUID } from 'node:crypto'\nimport type { BalanceScriptSnapshot } from './balance-config.ts'\nimport { evaluateBalanceScript, validateScriptBalance, type BalanceRequest } from './balance-script.ts'\nimport { BalanceNetworkError } from './balance-network.ts'\nimport type { BalanceInfo } from './types.ts'\nimport type { AccountBalanceSource } from './balance-account.ts'\n\nexport interface BalanceIdentity { apiKey: string; baseURL: string }\nexport interface ProviderBalance extends BalanceInfo { provider: string; scriptRevision: number; credentialGeneration: string }\ninterface Entry { identity: BalanceIdentity; revision: number; generation: string; controller: AbortController; pending?: Promise<ProviderBalance | undefined>; value?: ProviderBalance; nextAttempt: number; failures: number; lastFailure?: string }\ninterface Dependencies {\n  readScript(provider: string): Promise<BalanceScriptSnapshot>\n  resolveIdentity(provider: string): Promise<BalanceIdentity | undefined>\n  request(descriptor: BalanceRequest, baseURL: string, apiKey: string, signal: AbortSignal): Promise<unknown>\n  now?: () => number\n  /** Optional fixed-message diagnostic sink; receives no targets, headers or provider content. */\n  warn?: (message: string) => void\n}\n\n/** Demand-driven cache: one request per provider, no polling of unused providers. */\nexport class BalanceRegistry {\n  private entries = new Map<string, Entry>()\n  private stopped = false\n  private active = 0\n  private inspections = new Map<string, Promise<void>>()\n  private generations = new Map<string, number>()\n  private pendingRequests = new Set<Promise<ProviderBalance | undefined>>()\n  private accountSource: AccountBalanceSource | undefined\n  constructor(private dependencies: Dependencies) {}\n\n  /** Native accounts must never fall back to an unrelated API-key balance. */\n  setAccountSource(source: AccountBalanceSource | undefined): void { this.accountSource = source }\n\n  /** Read current credentials before serving cached data; never return an older generation.\n   * @param provider Exact configured provider identifier.\n   * @returns Current balance, or undefined while unconfigured, unavailable or throttled.\n   */\n  async get(provider: string): Promise<ProviderBalance | undefined> {\n    if (this.stopped) return undefined\n    if (provider === 'deepseek-account') {\n      // Teardown also waits for configuration reads before/after native I/O.\n      const pending = this.getAccount(provider)\n      this.pendingRequests.add(pending)\n      const release = () => { this.pendingRequests.delete(pending) }\n      void pending.then(release, release)\n      return pending\n    }\n    const preceding = this.inspections.get(provider)\n    let release!: () => void\n    const lock = new Promise<void>(resolve => { release = resolve })\n    this.inspections.set(provider, lock)\n    await preceding\n    try {\n      // Serialize identity reads, but release the lock before awaiting network I/O.\n      return (await this.prepare(provider)).result\n    } finally {\n      release()\n      if (this.inspections.get(provider) === lock) this.inspections.delete(provider)\n    }\n  }\n\n  private async getAccount(provider: string): Promise<ProviderBalance | undefined> {\n    const generation = this.generations.get(provider) ?? 0\n    const script = await this.dependencies.readScript(provider)\n    if (this.stopped || generation !== (this.generations.get(provider) ?? 0)) return undefined\n    if (script.status !== 'valid') { this.invalidate(provider); return undefined }\n    const value = await this.accountSource?.get()\n    const latest = await this.dependencies.readScript(provider)\n    if (this.stopped || generation !== (this.generations.get(provider) ?? 0)\n      || latest.revision !== script.revision || latest.status !== 'valid') return undefined\n    return value === undefined ? undefined : { ...value, scriptRevision: script.revision }\n  }\n\n  private async prepare(provider: string): Promise<{ result?: ProviderBalance | Promise<ProviderBalance | undefined> }> {\n    if (this.stopped) return {}\n    const generation = this.generations.get(provider) ?? 0\n    const [script, identity] = await Promise.all([this.dependencies.readScript(provider), this.dependencies.resolveIdentity(provider)])\n    if (this.stopped || generation !== (this.generations.get(provider) ?? 0)) return {}\n    if (script.status !== 'valid' || !script.request || !identity) { this.invalidate(provider); return {} }\n    let entry = this.entries.get(provider)\n    if (!entry || entry.revision !== script.revision || entry.identity.apiKey !== identity.apiKey || entry.identity.baseURL !== identity.baseURL) {\n      this.invalidate(provider)\n      entry = { identity, revision: script.revision, generation: randomUUID(), controller: new AbortController(), nextAttempt: 0, failures: 0 }\n      this.entries.set(provider, entry)\n    }\n    if (entry.pending) return { result: entry.pending }\n    const now = this.dependencies.now ?? Date.now\n    if (now() < entry.nextAttempt || this.active >= 4) return entry.value ? { result: entry.value } : {}\n    const current = entry\n    this.active++\n    current.pending = (async () => {\n      try {\n        const raw = await this.dependencies.request(script.request!, identity.baseURL, identity.apiKey, current.controller.signal)\n        const balance = validateScriptBalance(await evaluateBalanceScript(script.script, raw))\n        const [latestScript, latestIdentity] = await Promise.all([this.dependencies.readScript(provider), this.dependencies.resolveIdentity(provider)])\n        if (this.stopped || current.controller.signal.aborted || this.entries.get(provider) !== current) return undefined\n        if (latestScript.revision !== current.revision || latestScript.status !== 'valid'\n          || latestIdentity?.apiKey !== identity.apiKey || latestIdentity.baseURL !== identity.baseURL) { this.invalidate(provider); return undefined }\n        current.value = { ...balance, updatedAt: now(), provider, scriptRevision: script.revision, credentialGeneration: current.generation }\n        current.failures = 0\n        current.lastFailure = undefined\n        current.nextAttempt = now() + 15_000\n        return current.value\n      } catch (error) {\n        // No upstream exception or response content is exposed to logs or clients.\n        delete current.value\n        current.failures++\n        // Recovery stays fast: an ordinary transport failure waits one poll interval instead of\n        // growing exponentially, so a restarted proxy is picked up by the next scheduled read.\n        // An upstream 429 keeps the wait it asked for; a policy refusal keeps the same short\n        // interval because the address rule is recorded rather than the exemption widened.\n        const requested = error instanceof BalanceNetworkError ? error.retryAfterMs : undefined\n        current.nextAttempt = now() + (requested ?? 15_000)\n        // One diagnostic per failure streak or classification change; never per retry.\n        const kind = error instanceof BalanceNetworkError ? error.kind : 'transport'\n        if (current.failures === 1 || current.lastFailure !== kind) this.dependencies.warn?.('dsh-token-monitor: balance query failed (' + kind + ')')\n        current.lastFailure = kind\n        return undefined\n      } finally { this.active--; delete current.pending }\n    })()\n    const pending = current.pending\n    this.pendingRequests.add(pending)\n    void pending.finally(() => this.pendingRequests.delete(pending))\n    return { result: pending }\n  }\n\n  /** Cancel a provider's obsolete request and drop its cached balance.\n   * @param provider Exact provider identifier.\n   */\n  invalidate(provider: string): void {\n    if (provider === 'deepseek-account') this.accountSource?.invalidate()\n    this.generations.set(provider, (this.generations.get(provider) ?? 0) + 1)\n    this.entries.get(provider)?.controller.abort()\n    this.entries.delete(provider)\n  }\n\n  /** Cancel all work when the owning plugin context is disposed. */\n  async stop(): Promise<void> {\n    this.stopped = true\n    for (const provider of this.entries.keys()) this.invalidate(provider)\n    const accountStop = this.accountSource?.stop()\n    await Promise.allSettled([...this.inspections.values(), ...this.pendingRequests, ...(accountStop ? [accountStop] : [])])\n  }\n}\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/balance-script.ts",
      "content": "/** Keyless balance adapters evaluated inside a bounded QuickJS WebAssembly runtime. */\nimport { getQuickJS } from 'quickjs-emscripten'\nimport { validateBalancePath } from './balance-path.ts'\nexport { validateBalancePath } from './balance-path.ts'\n\nexport const MAX_BALANCE_SCRIPT_BYTES = 32_768\nexport const MAX_BALANCE_RESPONSE_BYTES = 262_144\n\n/** One credential-bearing request path, resolved against a Host-private provider endpoint. */\nexport interface BalanceRequest { path: string; method: 'GET' | 'POST'; auth: 'bearer' | 'x-api-key'; body?: string }\n/** Validated script output; credits remain distinct from monetary currencies. */\nexport interface ScriptBalance { currency: string; totalBalance: number; grantedBalance: number; toppedUpBalance: number; isAvailable: boolean; display?: string; windows?: ScriptBalanceWindow[] }\n/** One rolling usage window (for example a 5-hour or weekly plan quota). */\nexport interface ScriptBalanceWindow { label: string; used: number; total: number; resetAt?: number }\n\nconst MAX_BALANCE_WINDOWS = 8\n\n/** Coerce one flexible window figure: plain or decimal-string numbers only. */\nfunction windowNumber(value: unknown, message: string): number | undefined {\n  if (value === undefined) return undefined\n  const result = amount(value)\n  if (result < 0) throw new Error(message)\n  return result\n}\n\n/** Accept an epoch-milliseconds number or an ISO-8601 date string. */\nfunction coerceResetAt(value: unknown): number | undefined {\n  if (value === undefined) return undefined\n  if (typeof value === 'number' && Number.isFinite(value)) return value\n  if (typeof value === 'string' && value.trim()) {\n    const parsed = Date.parse(value)\n    if (Number.isFinite(parsed)) return parsed\n  }\n  throw new Error('Invalid balance window reset time')\n}\n\nfunction balanceWindows(value: unknown): ScriptBalanceWindow[] | undefined {\n  if (value === undefined) return undefined\n  if (!Array.isArray(value) || value.length > MAX_BALANCE_WINDOWS) throw new Error('Invalid balance windows')\n  return value.map((item, index) => {\n    const entry = object(item)\n    // Unknown extra fields are ignored rather than rejected: adapters may\n    // carry provider metadata alongside the window figures.\n    const label = entry.label === undefined ? `Window ${index + 1}` : entry.label\n    if (typeof label !== 'string' || !label.trim() || label.length > 16) throw new Error('Invalid balance window label')\n    const total = windowNumber(entry.total, 'Invalid balance window total')\n    if (total === undefined) throw new Error('Invalid balance window total')\n    const percent = windowNumber(entry.percent, 'Invalid balance window percent')\n    if (percent !== undefined && percent > 100) throw new Error('Invalid balance window percent')\n    let used: number\n    if (entry.used !== undefined) used = windowNumber(entry.used, 'Invalid balance window usage') ?? Number.NaN\n    else if (entry.remaining !== undefined) used = Math.max(total - (windowNumber(entry.remaining, 'Invalid balance window remaining') ?? -1), 0)\n    else if (percent !== undefined) used = total * percent / 100\n    else throw new Error('Invalid balance window usage')\n    if (!Number.isFinite(used) || used < 0) throw new Error('Invalid balance window usage')\n    const rounded = Math.round(used * 100) / 100\n    const resetAt = coerceResetAt(entry.resetAt)\n    return resetAt === undefined\n      ? { label, used: rounded, total }\n      : { label, used: rounded, total, resetAt }\n  })\n}\n\nfunction object(value: unknown): Record<string, unknown> {\n  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected an object')\n  return value as Record<string, unknown>\n}\n\n/** Run one adapter phase with no Node, environment, module loader, timers or network globals.\n * @param script Complete expression returning { request, parse(response) }.\n * @param response JSON response for parsing; omitted when inspecting the request.\n * @returns JSON copied out of the isolated interpreter.\n */\nexport async function evaluateBalanceScript(script: string, response?: unknown): Promise<unknown> {\n  if (Buffer.byteLength(script, 'utf8') > MAX_BALANCE_SCRIPT_BYTES) throw new Error('Balance script exceeds 32 KiB')\n  const quickjs = await getQuickJS()\n  const runtime = quickjs.newRuntime()\n  runtime.setMemoryLimit(8 * 1024 * 1024)\n  runtime.setMaxStackSize(256 * 1024)\n  const deadline = Date.now() + 100\n  runtime.setInterruptHandler(() => Date.now() >= deadline)\n  const vm = runtime.newContext()\n  try {\n    const responseJson = response === undefined ? undefined : JSON.stringify(response)\n    if (responseJson !== undefined && Buffer.byteLength(responseJson) > MAX_BALANCE_RESPONSE_BYTES) throw new Error('Balance response exceeds 256 KiB')\n    const value = vm.evalCode(`\"use strict\"; (() => {\n      const adapter = (${script}\\n);\n      if (!adapter || typeof adapter.parse !== 'function') throw new Error('Expected request and parse(response)');\n      const result = ${responseJson === undefined ? 'adapter.request' : `adapter.parse(${responseJson})`};\n      if (result && typeof result.then === 'function') throw new Error('Async adapters are unsupported');\n      return JSON.stringify(result);\n    })()`, 'balance-adapter.js')\n    if (value.error) {\n      // Do not dump untrusted error messages, which may contain response secrets.\n      value.error.dispose()\n      throw new Error('Balance script failed validation or exceeded execution limits')\n    }\n    try {\n      const json = vm.getString(value.value)\n      if (Buffer.byteLength(json) > MAX_BALANCE_RESPONSE_BYTES) throw new Error('Balance script output is too large')\n      return JSON.parse(json) as unknown\n    } finally { value.value.dispose() }\n  } finally { vm.dispose(); runtime.dispose() }\n}\n\n/** Validate the relative request path before Host resolves its private HTTPS endpoint.\n * @param value Untrusted request descriptor from the interpreter.\n * @returns Canonical bounded request.\n */\nexport function validateBalanceRequest(value: unknown): BalanceRequest {\n  const item = object(value)\n  if (Object.keys(item).some(key => !['path', 'method', 'auth', 'body'].includes(key))) throw new Error('Unsupported balance request field')\n  const path = validateBalancePath(item.path)\n  if (item.method !== 'GET' && item.method !== 'POST') throw new Error('Balance request must use GET or POST')\n  if (item.auth !== 'bearer' && item.auth !== 'x-api-key') throw new Error('Unsupported balance authentication')\n  if (item.body !== undefined && (typeof item.body !== 'string' || Buffer.byteLength(item.body) > 8192 || item.method !== 'POST')) throw new Error('Invalid balance request body')\n  return { path, method: item.method, auth: item.auth, ...(item.body === undefined ? {} : { body: item.body as string }) }\n}\n\nfunction amount(value: unknown): number {\n  if ((typeof value !== 'number' && typeof value !== 'string') || (typeof value === 'string' && !/^-?\\d+(?:\\.\\d+)?$/.test(value))) throw new Error('Balance amount must be a decimal number')\n  const result = Number(value)\n  if (!Number.isFinite(result) || Math.abs(result) > 1e12) throw new Error('Balance amount is out of range')\n  return result\n}\n\n/** Validate amounts without coercing credits into a monetary currency.\n *\n * Flexible shape: when valid `windows` are present, `currency` and\n * `totalBalance` may be omitted (they default to `credits` and the primary\n * window's remaining credits), so a window-only script stays short.\n * @param value Untrusted adapter result.\n * @returns Bounded balance fields for the UI.\n */\nexport function validateScriptBalance(value: unknown): ScriptBalance {\n  const item = object(value)\n  const windows = balanceWindows(item.windows)\n  const hasWindows = !!windows?.length\n  const currency = item.currency === undefined ? (hasWindows ? 'credits' : undefined) : item.currency\n  if (typeof currency !== 'string' || !/^(?:[A-Z]{3}|credits)$/.test(currency)) throw new Error('Balance currency must be an ISO code or credits')\n  if (item.isAvailable !== undefined && typeof item.isAvailable !== 'boolean') throw new Error('Invalid balance availability')\n  if (item.totalBalance === undefined && !hasWindows) throw new Error('Balance amount must be a decimal number')\n  const totalBalance = item.totalBalance === undefined\n    ? Math.max(windows![0].total - windows![0].used, 0)\n    : amount(item.totalBalance)\n  // 通用展示文本：脚本可用一段自定义字符串覆盖「货币符号 + 金额」的默认渲染，\n  // 供百分比、双窗口等非货币形态使用；数值字段照常校验，动画与耗尽判定不受影响。\n  const rawDisplay = typeof item.display === 'string' ? item.display.trim().slice(0, 48) : undefined\n  const display = rawDisplay ? rawDisplay : undefined\n  return { currency, totalBalance,\n    grantedBalance: item.grantedBalance === undefined ? 0 : amount(item.grantedBalance),\n    toppedUpBalance: item.toppedUpBalance === undefined ? 0 : amount(item.toppedUpBalance),\n    isAvailable: item.isAvailable !== false, ...(display ? { display } : {}), ...(windows ? { windows } : {}) }\n}\n\n/** Official adapter seed; an explicitly empty saved script disables it. */\nexport const OFFICIAL_BALANCE_SCRIPT = `({\n  request: { path: \"/user/balance\", method: \"GET\", auth: \"bearer\" },\n  parse(response) {\n    const rows = response.balance_infos.filter(item => item && typeof item.currency === \"string\"\n      && [item.total_balance, item.granted_balance, item.topped_up_balance].every(value => typeof value === \"string\" && value.trim() && Number.isFinite(Number(value))));\n    rows.sort((a, b) => Number(Number(b.total_balance) > 0) - Number(Number(a.total_balance) > 0)\n      || Number(b.currency === \"CNY\") - Number(a.currency === \"CNY\")\n      || Number(b.total_balance) - Number(a.total_balance) || a.currency.localeCompare(b.currency));\n    const row = rows[0];\n    return { currency: row.currency, totalBalance: row.total_balance,\n      grantedBalance: row.granted_balance, toppedUpBalance: row.topped_up_balance,\n      isAvailable: response.is_available !== false };\n  }\n})`\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/collector-core.ts",
      "content": "/** Permanent usage capture; optional billing is supplied by its live module. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-agent'\nimport type { Session, SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { BillingSnapshot } from '@deepseek-ai/dsh-token-monitor-contract'\nimport { isValidUsageRecord, type UsageRecord } from './types.ts'\nimport type { UsageStorage } from './storage.ts'\n\nexport interface UsageCollectorOptions {\n  readBilling?: () => BillingSnapshot | undefined\n  priceRecord?: (record: UsageRecord, frozen: BillingSnapshot | undefined) => UsageRecord\n  onPersistedRecord?: (record: UsageRecord, kind: 'normal' | 'miss') => void\n  /** 会话用量行的唯一写入出口；缺省时不写入，宿主兼容判定由实现方负责。 */\n  appendUsageRecord?: (session: Session, record: UsageRecord) => void\n}\n\n/** Capture each live source event once, even while all optional modules are absent. */\nexport function attachUsageCollector(ctx: Context, storage: UsageStorage, options: UsageCollectorOptions): void {\n  const requests = new WeakMap<Session, { turn: number; step: number; billing: BillingSnapshot }>()\n  let active = true\n  ctx.effect(() => () => { active = false }, 'token-monitor: usage capture lifetime')\n  ctx.on('agent/assistant-stream', ({ agent, frame }) => {\n    if (frame.type === 'start') {\n      const billing = options.readBilling?.()\n      if (billing !== undefined) requests.set(agent.session, { turn: frame.turn, step: frame.step, billing: structuredClone(billing) })\n    } else if (frame.type === 'end') requests.delete(agent.session)\n  })\n  ctx.on('session/event', (session: Session, event: SessionEvent) => {\n    if (!active || event.type !== 'assistant/message') return\n    if (typeof session.firstLiveSeq === 'number' && event.seq < session.firstLiveSeq) return\n    const usage = event.data.usage, source = event.data.message.source\n    if (usage === undefined || source.kind !== 'model') return\n    const raw: UsageRecord = {\n      sessionId: session.id, turn: event.data.turn, step: event.data.step, sourceEventSeq: event.seq,\n      timestamp: event.time, provider: source.provider, model: source.model, inputTokens: usage.inputTokens,\n      outputTokens: usage.outputTokens, cacheReadTokens: usage.cacheReadTokens ?? 0, cacheWriteTokens: usage.cacheWriteTokens ?? 0,\n      reasoningTokens: usage.reasoningTokens ?? 0, cost: 0, costInput: 0, costOutput: 0, costCache: 0, costCacheRead: 0,\n      costCacheWrite: 0, peak: false, billingStatus: 'unpriced',\n    }\n    if (!isValidUsageRecord(raw)) return\n    const request = requests.get(session)\n    const frozen = request?.turn === raw.turn && request.step === raw.step ? request.billing : options.readBilling?.()\n    const record = options.priceRecord?.(raw, frozen) ?? raw\n    if (!isValidUsageRecord(record) || storage.add(record) === undefined) return\n    const kind = record.inputTokens > 0 || record.cacheWriteTokens > 0 ? 'miss' : 'normal'\n    options.onPersistedRecord?.(record, kind)\n    queueMicrotask(() => {\n      if (!active) return\n      options.appendUsageRecord?.(session, record)\n    })\n  })\n}\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/index.ts",
      "content": "/** Installed entry: loads verified modular payloads without recreating removed features. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { existsSync } from 'node:fs'\nimport { dirname, resolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { bootModules } from './module-bootstrap.ts'\nimport { registerUserSettings } from './user-settings.ts'\nimport type { TokenMonitorUserConfig } from './config-base.ts'\nimport type {} from '@deepseek-ai/dsh-session-projection'\nimport type {} from '@deepseek-ai/dsh-session-projection-cache'\nimport type {} from '@deepseek-ai/dsh-session-persistence'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type {} from '@deepseek-ai/dsh-client-connection'\nimport type {} from '../../wechat-notify/src/connection.ts'\n\nexport const name = 'dsh-token-monitor'\nexport { Config } from './config-base.ts'\nexport const inject = ['sessions', 'credentials', 'settings']\n\n/** Start the installed release; a whole-plugin tombstone leaves this loader inert.\n * @param ctx Host-owned plugin lifetime.\n */\nexport async function apply(ctx: Context, config: TokenMonitorUserConfig): Promise<void> {\n  registerUserSettings(ctx, config)\n  const pluginRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')\n  // Source checkouts keep the browser bundle beside the workspace package. A\n  // packed install has no workspace tree, so prefer the installed runtime/client\n  // payload and fall back to the monolithic package lib directory.\n  const sourceClient = resolve(pluginRoot, '../../packages/client/ui-token-monitor/lib')\n  const runtimeClient = resolve(pluginRoot, 'runtime/client')\n  const packagedClient = resolve(pluginRoot, 'lib')\n  const isSourceTree = pluginRoot.replaceAll('\\\\', '/').endsWith('/plugins/dsh-token-monitor')\n  const clientRoot = existsSync(runtimeClient) ? runtimeClient : isSourceTree ? sourceClient : packagedClient\n  await bootModules(ctx, pluginRoot, clientRoot)\n}\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/module-bootstrap.ts",
      "content": "/** This loader preserves whole-plugin removal until a complete verified package is installed again. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { access, readFile, mkdir } from 'node:fs/promises'\nimport { dirname, resolve } from 'node:path'\nimport { pathToFileURL } from 'node:url'\nimport { withFileLock } from '@deepseek-ai/dsh-atomic-write'\nimport { recoverModuleTransaction } from './module-transaction.ts'\nimport { atomicJson, compareReleaseVersions, validateManifest, verifyArtifact, type ArtifactRoots } from './module-files.ts'\nimport { ModuleManager } from './module-manager.ts'\nimport type * as Runtime from './runtime-host.ts'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\nimport { eraseRemovedPlugin } from './module-cleanup.ts'\nimport { acquireModuleLease, recoverModuleLock } from './module-lease.ts'\nimport { createRouteGuard } from './http-trust.ts'\n\n/**\n * runtime/ is generated by the packaging step and is not tracked, so a source\n * install that never ran it ships no payload. Check it before anything else so\n * the loader reports the remedy instead of a bare ENOENT on the manifest path,\n * and name the source-address case plus the uninstall-then-reinstall step that\n * actually clears it (a same-version reinstall is refused while the broken copy\n * is still listed as installed).\n */\nasync function assertInstalledPayload(runtime: string): Promise<void> {\n  try { await access(resolve(runtime, 'manifest.json')) }\n  catch (error) {\n    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n    throw new Error('dsh-damage-pulse: the installed payload is incomplete: runtime/manifest.json is '\n      + 'missing, so the plugin cannot start. The most common cause is installing from a source address '\n      + '(a repository URL, a `github:` spec, a source archive, or an unpacked source tree that was never '\n      + 'built), which ships no payload because only the packaging step generates it; a damaged or partly '\n      + 'extracted install looks the same. Install the published package for the profile you actually use: '\n      + '`dsh plugin --profile <profile> add dsh-damage-pulse`, or the .tgz from the GitHub Release. If the '\n      + 'target profile still lists a broken copy of the same version, uninstall it first and install '\n      + 'again; unbuilt source can build the payload before mounting it.')\n  }\n}\n\n/** Prefer a persisted module release after an in-place update, but let a newer package take over. */\nexport function selectBootManifest(packageManifest: unknown, stateManifest: unknown) {\n  const packaged = validateManifest(packageManifest)\n  if (stateManifest === undefined) return packaged\n  const persisted = validateManifest(stateManifest)\n  return compareReleaseVersions(persisted.version, packaged.version) >= 0 ? persisted : packaged\n}\n\nexport async function bootModules(ctx: Context, pluginRoot: string, clientRoot: string): Promise<void> {\n  const runtime = resolve(pluginRoot, 'runtime')\n  await assertInstalledPayload(runtime)\n  // Package managers replace node_modules during upgrades. Keep tombstones and\n  // the transaction journal in the profile, outside the installed payload.\n  const stateFile = resolve(pluginRoot, '..', '..', '.dsh-damage-pulse', 'module-state.json')\n  const legacyStateFile = resolve(runtime, 'state.json')\n  const roots: ArtifactRoots = { host: resolve(runtime, 'host'), assets: resolve(runtime, 'assets'), client: clientRoot }\n  await mkdir(dirname(stateFile), { recursive: true })\n  const releaseLease = await acquireModuleLease(stateFile)\n  ctx.effect(() => releaseLease, 'token-monitor: exclusive installed runtime')\n  await recoverModuleLock(stateFile)\n  const { manifest, removed } = await withFileLock(stateFile, async () => {\n    try { await readFile(stateFile, 'utf8') }\n    catch (error) {\n      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n      // In-place installations can migrate the old package-local state.\n      // A legacy transaction needs recovery with its original package first.\n      try {\n        await readFile(legacyStateFile + '.transaction.json', 'utf8')\n        throw new Error('LEGACY_MODULE_RECOVERY_REQUIRED')\n      } catch (journalError) {\n        if ((journalError as NodeJS.ErrnoException).code !== 'ENOENT') throw journalError\n      }\n      try { await atomicJson(stateFile, JSON.parse(await readFile(legacyStateFile, 'utf8'))) }\n      catch (legacyError) { if ((legacyError as NodeJS.ErrnoException).code !== 'ENOENT') throw legacyError }\n    }\n    await recoverModuleTransaction(stateFile, roots)\n    let state: { manifest?: unknown; wholePlugin?: { pending?: boolean }; removed?: Record<string, { pending?: boolean }> } | undefined\n    try { state = JSON.parse(await readFile(stateFile, 'utf8')) }\n    catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error }\n    const packaged = JSON.parse(await readFile(resolve(runtime, 'manifest.json'), 'utf8'))\n    // Pending deletion still owns the previous release's paths. Only a completed\n    // whole removal can evaluate a replacement package for reinstatement.\n    const pending = state?.wholePlugin?.pending || Object.values(state?.removed ?? {}).some(record => record.pending)\n    const manifest = state?.wholePlugin && pending && state.manifest\n      ? validateManifest(state.manifest) : selectBootManifest(packaged, state?.wholePlugin ? undefined : state?.manifest)\n    if (!state?.wholePlugin) for (const file of manifest.core) await verifyArtifact(roots, file)\n    return { manifest, removed: !!state?.wholePlugin }\n  })\n  if (removed) {\n    // Teardown and erasure precede deletion. A restart only retries remaining locked payload files.\n    const manager = await ModuleManager.open(manifest, stateFile, roots, {\n      stop: async () => {}, start: async () => {}, stopCore: async () => {}, startCore: async () => {},\n      // The whole-plugin record is authoritative; partial feature cleanup is subsumed.\n      eraseData: async (id, selection) => { if (id === 'plugin' && selection) await eraseRemovedPlugin(ctx, dshHomePath('data', 'dsh-token-monitor'), selection) },\n    }, true)\n    if (manager.snapshot().pluginRemoved) {\n      if (manager.snapshot().cleanupErrors?.includes('PLUGIN_REINSTALL_INCOMPLETE')) {\n        ctx.logger.warn('dsh-damage-pulse: PLUGIN_REINSTALL_INCOMPLETE — replacement package files are missing or damaged; remove the listed plugin in the desktop Plugins page, add a complete packaged .tgz or published package, then restart this profile.')\n      }\n      // The host still discovers the package's static client entry. Expose only\n      // the durable tombstone so that entry stays dormant after a restart.\n      ctx.inject(['webServer', 'connection'], web => {\n        const guard = createRouteGuard(web)\n        web.effect(() => web.webServer.register({\n          kind: 'exact', path: '/api/token-monitor/modules', handler: (req, res) => {\n            if (!guard(req, res)) return\n            if (req.method !== 'GET') { res.writeHead(405); res.end(); return }\n            res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' })\n            res.end(JSON.stringify(manager.snapshot()))\n          },\n        }), 'token-monitor: removed plugin snapshot')\n      })\n      return\n    }\n  }\n  const entry: typeof Runtime = await import(pathToFileURL(resolve(roots.host, 'manager.mjs')).href + `?v=${manifest.version}`)\n  await entry.apply(ctx, { roots, stateFile, manifest })\n}\n"
    },
