      "path": "plugins/dsh-token-monitor/src/runtime-host.ts",
      "content": "/** Awaited Cordis child lifetimes connect physical payloads to live services. */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { pathToFileURL } from 'node:url'\nimport { resolve } from 'node:path'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\nimport type { ModuleReleaseManifest } from '@deepseek-ai/dsh-token-monitor-contract'\nimport { TOKEN_MONITOR_ASSET_BASE } from '@deepseek-ai/dsh-token-monitor-contract'\nimport type { ModuleServices, RuntimeFeature } from './module-services.ts'\nimport type * as Core from './runtime-core.ts'\nimport type { ArtifactRoots } from './module-files.ts'\nimport { ModuleManager, type ModuleLifecycle } from './module-manager.ts'\nimport { registerModuleRoutes } from './module-routes.ts'\nimport { createTokenMonitorAssetHandler } from './assets.ts'\nimport { synchronizeClientEntry } from './client-entry.ts'\n\nexport interface RuntimeOptions {\n  roots: ArtifactRoots\n  stateFile: string\n  manifest: ModuleReleaseManifest\n  /** Source-plane tests supply actual source modules without consuming built output. */\n  loadCore?: () => Promise<typeof Core>\n  loadFeature?: (id: string) => Promise<RuntimeFeature>\n  dataDir?: string\n  /** 服务构造注入点；缺省由 core 在宿主上下文里自建。 */\n  services?: (ctx: Context) => Promise<ModuleServices>\n}\n// Cordis treats a plugin apply() return value as an effect: returning a plain\n// object throws TypeError: Invalid effect. Lifecycle here is registered through\n// ctx.effect / ctx.inject, so the entry point deliberately yields nothing.\nexport async function apply(ctx: Context, options: RuntimeOptions): Promise<void> {\n  const { roots, stateFile, manifest } = options\n  // Must finish before ModuleManager.open acknowledges the completed restart.\n  await synchronizeClientEntry(roots, manifest)\n  const core: typeof Core = options.loadCore ? await options.loadCore() : await import(pathToFileURL(resolve(roots.host, 'core.mjs')).href + `?v=${manifest.version}`)\n  const services = options.services !== undefined\n    ? await options.services(ctx)\n    : await core.createServices(ctx, roots.assets, options.dataDir ?? dshHomePath('data', 'dsh-token-monitor'))\n  type Child = ReturnType<Context['plugin']>\n  const children = new Map<string, Child>()\n  let coreChild: Child | undefined, coreRuntime: ReturnType<typeof core.apply> | undefined\n  let manager: ModuleManager\n  const lifecycle: ModuleLifecycle = {\n    async start(id) {\n      if (children.has(id)) return\n      const feature: RuntimeFeature = options.loadFeature ? await options.loadFeature(id) : await import(pathToFileURL(resolve(roots.host, `${id}.mjs`)).href + `?v=${manifest.version}`)\n      const child = ctx.plugin({ name: `token-monitor-${id}`, apply: (scope: Context) => feature.apply(scope, services) })\n      children.set(id, child)\n      try { await child.await() } catch (error) { await child.dispose(); children.delete(id); throw error }\n    },\n    async stop(id) {\n      await coreRuntime?.drainSettings()\n      const child = children.get(id)\n      if (child) { await child.dispose(); children.delete(id) }\n    },\n    async startCore() {\n      if (coreChild) return\n      coreChild = ctx.plugin({ name: 'token-monitor-background-core', apply(scope: Context) { coreRuntime = core.apply(scope, services, id => manager.isInstalled(id)) } })\n      await coreChild.await()\n    },\n    async stopCore() {\n      if (coreChild) { await coreChild.dispose(); coreChild = undefined; coreRuntime = undefined }\n    },\n    async eraseData(id, selection = { configuration: true, history: true }) {\n      const resume = !!coreChild && id !== 'plugin'\n      if (selection.history) await lifecycle.stopCore()\n      try { await core.eraseData(ctx, services, id, selection) }\n      finally { if (selection.history && resume) await lifecycle.startCore() }\n    },\n  }\n  manager = await ModuleManager.open(manifest, stateFile, roots, lifecycle)\n  ctx.inject(['webServer'], web => {\n    for (const directory of ['settings-ui/cute', 'whale-girl']) {\n      // The desktop shell answers every /assets/** request from its own frozen\n      // front-end bundle, so plugin images must live under their own\n      // document-relative prefix to reach this Host at all.\n      const path = `${TOKEN_MONITOR_ASSET_BASE}/${directory}`\n      const serve = createTokenMonitorAssetHandler(path, resolve(roots.assets, directory))\n      web.effect(() => web.webServer.register({ kind: 'prefix', path, handler: (req, res) => {\n        if (manager.snapshot().pluginRemoved && !manager.snapshot().cleanupPending || directory === 'whale-girl' && !manager.isInstalled('pet')) { res.writeHead(404); res.end(); return }\n        return serve(req, res)\n      } }), 'token-monitor: owned asset route')\n    }\n  })\n  if (!manager.snapshot().pluginRemoved) {\n    // Pricing and observation are available before raw capture can receive an event.\n    const ordered = new Set(['wechat', 'billing', 'notify', 'overview', 'pet', ...manifest.modules.map(module => module.id)])\n    for (const id of ordered) if (manager.isInstalled(id)) await lifecycle.start(id)\n    await lifecycle.startCore()\n  }\n  ctx.inject(['webServer', 'connection'], web => registerModuleRoutes(web, manager, stateFile, undefined, () => services))\n}\n"
    },
    {
      "path": "plugins/dsh-token-monitor/src/storage.ts",
      "content": "/**\n * 会话累计存储 + 单次用量明细持久化（JSONL）。\n * 会话累计（tokenCost projection）已由 session-projection-cache 持久化；\n * 这里额外落盘单次用量明细，供历史查询与导出。\n * @module dsh-token-monitor/storage\n */\n\nimport { appendFileSync, mkdirSync, readFileSync } from 'node:fs'\nimport { replaceHistoryFile } from './history-file.ts'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\nimport { join } from 'node:path'\nimport { beijingDateKey } from './todaySpend.ts'\nimport { isValidUsageRecord, normalizeUsageRecord, type SessionSummary, type TodaySpendInfo, type UsageRecord } from './types.ts'\n\n/** 明细数据目录：~/.dsh/data/dsh-token-monitor/ */\nconst DATA_DIR = dshHomePath('data', 'dsh-token-monitor')\n\n  /** 保留参数用于兼容既有构造器；历史记录按写入时状态读取，不按当前规则重算。 */\nexport type UsageEligibility = (record: UsageRecord) => boolean\n\n/** 按会话累计用量与金额，并追加持久化单次明细。 */\nexport class UsageStorage {\n  private readonly summaries = new Map<string, SessionSummary>()\n  private readonly records: UsageRecord[] = []\n  private readonly dailySpend = new Map<string, { cost: number; calls: number }>()\n  private readonly seenSourceEvents = new Set<string>()\n  private readonly dataDir: string\n\n  /** Clear plugin-owned history without touching host session logs. */\n  clear(): void {\n    this.replaceHistory([])\n  }\n\n  /** Erase saved monetary decisions while retaining token usage; never reprice. */\n  clearBilling(): void {\n    this.replaceHistory(this.records.map(record => {\n      const cleared: UsageRecord = { ...record, cost: 0, costInput: 0, costOutput: 0,\n        costCache: 0, costCacheRead: 0, costCacheWrite: 0, billingStatus: 'unpriced', peak: false }\n      delete cleared.billingRule\n      delete cleared.billingApplied\n      delete cleared.billingReason\n      delete cleared.billingRuleVersion\n      delete cleared.modelMultiplier\n      return cleared\n    }))\n  }\n\n  private replaceHistory(records: UsageRecord[]): void {\n    replaceHistoryFile(join(this.dataDir, 'usage.jsonl'), records.map(record => JSON.stringify(record) + '\\n').join(''))\n    this.records.length = 0\n    this.summaries.clear(); this.dailySpend.clear(); this.seenSourceEvents.clear()\n    this.loadHistory()\n  }\n\n  constructor(_isEligible: UsageEligibility, dataDir: string = DATA_DIR) {\n    this.dataDir = dataDir\n    try {\n      mkdirSync(this.dataDir, { recursive: true })\n    } catch (error) {\n      console.warn(`[dsh-token-monitor] 创建数据目录失败: ${String(error)}`)\n    }\n    this.loadHistory()\n  }\n\n  /** 冷启动回读历史明细（fail-soft：文件缺失/损坏行静默跳过）。 */\n  private loadHistory(): void {\n    try {\n      const text = readFileSync(join(this.dataDir, 'usage.jsonl'), 'utf8')\n      let excluded = 0\n      for (const line of text.split('\\n')) {\n        const trimmed = line.trim()\n        if (trimmed === '') continue\n        try {\n          const record = normalizeUsageRecord(JSON.parse(trimmed))\n          if (record !== undefined && isValidUsageRecord(record)) {\n            if (this.isDuplicateSourceEvent(record)) continue\n            this.records.push(record)\n            this.summaries.set(record.sessionId, this.fold(record))\n            this.addToDailySpend(record)\n          }\n          else excluded++\n        } catch {\n          // 跳过损坏的行\n        }\n      }\n      if (this.records.length > 0) {\n        console.log(`[dsh-token-monitor] 已加载 ${this.records.length} 条历史明细`)\n      }\n      if (excluded > 0) {\n        console.log(`[dsh-token-monitor] 已从运行时汇总排除 ${excluded} 条不合格历史明细（原始 JSONL 未修改）`)\n      }\n    } catch {\n      // 首次运行无文件，静默\n    }\n  }\n\n  /** 将明细折叠到会话摘要；冷启动与新增路径共用，避免摘要状态分叉。 */\n  private fold(record: UsageRecord): SessionSummary {\n    const prev = this.summaries.get(record.sessionId)\n    if (prev === undefined) {\n      return {\n        sessionId: record.sessionId,\n        calls: 1,\n        inputTokens: record.inputTokens,\n        cacheReadTokens: record.cacheReadTokens,\n        cacheWriteTokens: record.cacheWriteTokens,\n        outputTokens: record.outputTokens,\n        totalTokens: record.inputTokens + record.cacheReadTokens + record.cacheWriteTokens + record.outputTokens,\n        cost: record.cost,\n        lastActivity: record.timestamp,\n      }\n    }\n    return {\n      ...prev,\n      calls: prev.calls + 1,\n      inputTokens: prev.inputTokens + record.inputTokens,\n      cacheReadTokens: prev.cacheReadTokens + record.cacheReadTokens,\n      cacheWriteTokens: prev.cacheWriteTokens + record.cacheWriteTokens,\n      outputTokens: prev.outputTokens + record.outputTokens,\n      totalTokens: prev.totalTokens + record.inputTokens + record.cacheReadTokens + record.cacheWriteTokens + record.outputTokens,\n      cost: prev.cost + record.cost,\n      lastActivity: record.timestamp,\n    }\n  }\n\n  /** 将合格明细累加到北京时间日期索引，避免今日消费查询重复扫描全部历史。 */\n  private addToDailySpend(record: UsageRecord): void {\n    if (record.billingStatus !== undefined && record.billingStatus !== 'priced') return\n    const date = beijingDateKey(record.timestamp)\n    const previous = this.dailySpend.get(date)\n    if (previous === undefined) {\n      this.dailySpend.set(date, { cost: record.cost, calls: 1 })\n      return\n    }\n    previous.cost += record.cost\n    previous.calls += 1\n  }\n\n  /** 把一条单次记录累加到对应会话，并追加持久化明细。 */\n  add(record: UsageRecord): SessionSummary | undefined {\n    if (!isValidUsageRecord(record)) return undefined\n    if (this.isDuplicateSourceEvent(record)) return undefined\n    const next = this.fold(record)\n    this.summaries.set(record.sessionId, next)\n\n    // 明细：内存缓存 + JSONL 追加（fail-soft，落盘失败不影响运行时）。\n    this.records.push(record)\n    this.addToDailySpend(record)\n    try {\n      appendFileSync(join(this.dataDir, 'usage.jsonl'), `${JSON.stringify(record)}\\n`, 'utf8')\n    } catch (error) {\n      console.warn(`[dsh-token-monitor] 明细落盘失败: ${String(error)}`)\n    }\n\n    return next\n  }\n\n  private isDuplicateSourceEvent(record: UsageRecord): boolean {\n    if (record.sourceEventSeq === undefined) return false\n    const key = JSON.stringify([record.sessionId, record.sourceEventSeq])\n    if (this.seenSourceEvents.has(key)) return true\n    this.seenSourceEvents.add(key)\n    return false\n  }\n\n  get(sessionId: string): SessionSummary | undefined {\n    return this.summaries.get(sessionId)\n  }\n\n  list(): SessionSummary[] {\n    return [...this.summaries.values()]\n  }\n\n  /** 单次用量明细（可按会话过滤）。 */\n  history(sessionId?: string): UsageRecord[] {\n    if (sessionId === undefined) return [...this.records]\n    return this.records.filter((record) => record.sessionId === sessionId)\n  }\n\n  /** 按北京时间自然日聚合当前运行时已通过资格门禁的记录。 */\n  todaySpend(now = Date.now()): TodaySpendInfo {\n    const date = beijingDateKey(now)\n    const summary = this.dailySpend.get(date)\n    return {\n      date,\n      timeZone: 'Asia/Shanghai',\n      currency: 'CNY',\n      cost: summary?.cost ?? 0,\n      calls: summary?.calls ?? 0,\n      updatedAt: now,\n    }\n  }\n}\n"
    }
  ],
